import{_ as t,o as a,c as n,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"FR 3.5.10 - Cancel Content Request","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-10-cancel-request/spec.md","filePath":"feature/media-package-campaign/3-5-10-cancel-request/spec.md"}'),c={name:"feature/media-package-campaign/3-5-10-cancel-request/spec.md"};function i(o,e,s,l,d,u){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="fr-3-5-10-cancel-content-request" tabindex="-1">FR 3.5.10 - Cancel Content Request <a class="header-anchor" href="#fr-3-5-10-cancel-content-request" aria-label="Permalink to &quot;FR 3.5.10 - Cancel Content Request&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Status</td><td>Ready for technical review</td></tr><tr><td>Roles</td><td>Requesting Client</td></tr><tr><td>Delivery task</td><td>DA-E50-10</td></tr></tbody></table><h2 id="outcome" tabindex="-1">Outcome <a class="header-anchor" href="#outcome" aria-label="Permalink to &quot;Outcome&quot;">​</a></h2><p>The requesting Client can cancel a request only while it remains <code>PENDING</code>.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li><code>DELETE /api/v1/workspaces/{workspaceId}/content-requests/{requestId}</code> is permitted only to creator and only from <code>PENDING</code>.</li><li>A non-pending request returns <code>409 REQUEST_NOT_CANCELLABLE</code>.</li><li>Cancellation never creates a task or alters an existing generated task.</li><li>Confirmed 2026-10-14: Manager marking Campaign COMPLETED automatically cancels PENDING Requests with history; IN_PROGRESS is not cancelled. This is a system consequence of completion, not a general Manager cancel endpoint. See ../request-completion-validation/spec.md.</li><li>Manager receipt and Client cancellation compete through an atomic status/version predicate; only one succeeds. Owner/Manager cannot cancel on behalf of the requester in this scope.</li></ul><h2 id="ui-contract" tabindex="-1">UI contract <a class="header-anchor" href="#ui-contract" aria-label="Permalink to &quot;UI contract&quot;">​</a></h2><p>Use existing confirmation UI with parallel vi/en <code>requests.cancelDialog.*</code> and <code>requests.status.cancelled</code> keys. Retain cancelled requests in list/detail history, with no edit/reopen action. Support keyboard focus, pending/error states and semantic light/dark tokens.</p><h2 id="retention-rule" tabindex="-1">Retention rule <a class="header-anchor" href="#retention-rule" aria-label="Permalink to &quot;Retention rule&quot;">​</a></h2><p>Cancellation is a terminal <code>CANCELLED</code> status, not a hard delete. It remains visible in appropriate history/audit views and can never generate a task.</p>',10)])])}const m=t(c,[["render",i]]);export{h as __pageData,m as default};
